export default async function Page() {
  const cookieStore = await cookies(); // Next.js 15: cookies() стал async
  const session = cookieStore.get('session'); // любое чтение cookies → dynamic rendering

  // Data Cache внутри динамического маршрута всё равно работает
  const products = await fetch(url, { cache: 'force-cache' }).then((r) => r.json());

  return <ProductList products={products} session={session} />;
}
